/* AIGAME PWA V23 service worker — generated by tools/build_pwa_v23.py.
 *
 * BundleGate-safe by construction:
 *   - cache-first ONLY for manifest + icons (+ the static landing shell used
 *     as an offline navigation fallback);
 *   - network-first, never cached, for index.html / index.pck / index.wasm /
 *     *.js / RELEASE_BUILD.txt / bundles_index.json / bundles/* and every other
 *     same-origin asset.  A stale unsigned PCK can therefore never be served.
 *   - no COOP/COEP response rewriting (Godot's threads path is untouched).
 *   - no token or signing secret is present in this file.
 */
"use strict";
const CACHE_VERSION = "v23-20261028101015-55ed0b39";
const CACHE_NAME = "aigame-pwa-" + CACHE_VERSION;
const PRECACHE = [
  "./manifest.webmanifest",
  "./icon-192.png",
  "./icon-512.png",
  "./icon-maskable-512.png",
  "./favicon.ico",
  "./index.apple-touch-icon.png",
  "./index.icon.png",
  "./landing.html"
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k)));
    await self.clients.claim();
    const clients = await self.clients.matchAll({ type: "window" });
    for (const c of clients) c.postMessage({ type: "PWA_SW_ACTIVE", version: CACHE_VERSION });
  })());
});

self.addEventListener("message", (event) => {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
});

function precacheRequest(pathname) {
  return PRECACHE.some((rel) => new URL(rel, self.registration.scope).pathname === pathname);
}

self.addEventListener("fetch", (event) => {
  const req = event.request;
  if (req.method !== "GET") return;
  let url;
  try { url = new URL(req.url); } catch (e) { return; }
  if (url.origin !== self.location.origin) return;
  if (url.pathname.endsWith("/sw.js")) return;

  // Cache-first: manifest + icons + the static landing shell only.
  if (precacheRequest(url.pathname)) {
    event.respondWith(
      caches.match(req).then((hit) => {
        if (hit) return hit;
        return fetch(req).then((resp) => {
          if (resp && resp.ok) {
            const copy = resp.clone();
            caches.open(CACHE_NAME).then((c) => c.put(req, copy));
          }
          return resp;
        });
      })
    );
    return;
  }

  // Navigations: always try the network first; only go offline to landing.
  if (req.mode === "navigate") {
    event.respondWith(
      fetch(req, { cache: "no-cache" }).catch(() => {
        const shell = new URL("./landing.html", self.registration.scope).href;
        return caches.match(shell).then((hit) =>
          hit || new Response(
            "Offline / 离线：signed game assets are never served from a stale cache.",
            { status: 503, headers: { "Content-Type": "text/plain; charset=utf-8" } }
          )
        );
      })
    );
    return;
  }

  // Signed / game / JS / JSON / everything else: network-first, never stored.
  event.respondWith(
    fetch(req, { cache: "no-cache" }).catch(() =>
      new Response("", { status: 503, statusText: "Offline — signed asset not cached" })
    )
  );
});
